import{_ as i,o as a,c as e,ap as t}from"./chunks/framework.CuFS6FqL.js";const l="/images/pentestai-start-sandbox.png",n="/images/pentestai-force-checklist.png",g=JSON.parse('{"title":"Using AI","description":"","frontmatter":{"Title":"Local AI tools setup","Description":"Step by step guide to setup AI tools with internal litellm host."},"headers":[],"relativePath":"organization/human-resources/ai-tool-setup.md","filePath":"organization/human-resources/ai-tool-setup.md"}'),o={name:"organization/human-resources/ai-tool-setup.md"};function r(h,s,p,d,c,k){return a(),e("div",null,[...s[0]||(s[0]=[t(`<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /organization/human-resources/ai-tool-setup.md for this page in Markdown format</div><h1 id="using-ai" tabindex="-1">Using AI <a class="header-anchor" href="#using-ai" aria-label="Permalink to &quot;Using AI&quot;">​</a></h1><p>We host our own internal AI models for use with AI tools and integrations. You can access them through LiteLLM at <a href="https://litellm.internal.syslifters.com/" target="_blank" rel="noreferrer">https://litellm.internal.syslifters.com/</a>.</p><p>You will receive your own LiteLLM key so you can use (almost) any AI-powered software in combination with our self-hosted models.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><h3 id="claude-cli" tabindex="-1">Claude CLI <a class="header-anchor" href="#claude-cli" aria-label="Permalink to &quot;Claude CLI&quot;">​</a></h3><ol><li>Install with winget <code>winget install -e --id Anthropic.ClaudeCode</code></li><li>To use our own LLMs with claude cli, set the following environment variables</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Powershell</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$env:CLAUDE_CODE_DISABLE_EXPERIMENTAL_BETAS = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       # opt out of using beta versions</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$env:DISABLE_PROMPT_CACHING = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                       # disable prompt caching</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$env:ANTHROPIC_BASE_URL = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://litellm.internal.syslifters.com/&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # set local litellm url </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$env:ANTHROPIC_AUTH_TOKEN = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;YOUR_LITELLM_TOKEN&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                        # set your personal auth token</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CLAUDE_CODE_DISABLE_EXPERIMENTAL_BETAS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DISABLE_PROMPT_CACHING</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ANTHROPIC_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://litellm.internal.syslifters.com/</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ANTHROPIC_AUTH_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">YOUR_LITELLM_TOKEN</span></span></code></pre></div><ol start="3"><li>Now run claude with the default model</li></ol><div class="language-Powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">claude.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model local_model_default  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># alias to use currently running local model, you can choose any running model</span></span></code></pre></div><h3 id="cline" tabindex="-1">Cline <a class="header-anchor" href="#cline" aria-label="Permalink to &quot;Cline&quot;">​</a></h3><p>Cline is a VSCode extension, which adds custom AIs to your IDE. It allows you to use many different AI providers:</p><ul><li>Install cline (<a href="https://cline.bot/" target="_blank" rel="noreferrer">https://cline.bot/</a>) extension from marketplace in e.g. VSCode.</li><li>When asked &quot;How will you use Cline?&quot; click &quot;Bring my own API key&quot;</li><li>Use the following configuration: <ul><li>API Provider: OpenAI Compatible</li><li>Base URL: <a href="https://litellm.internal.syslifters.com/v1" target="_blank" rel="noreferrer">https://litellm.internal.syslifters.com/v1</a></li><li>API Key: <code>Bearer YOUR_LITELLM_TOKEN</code></li><li>Model: <code>local_model_default</code></li></ul></li></ul><h3 id="cursor" tabindex="-1">Cursor <a class="header-anchor" href="#cursor" aria-label="Permalink to &quot;Cursor&quot;">​</a></h3><p>You can ask for a Cursor subscription if you need one. You can also bring your own model.</p><p>If using Cursor, make sure to maintain a global ignorelist to hold the agent back from accessing sensitive files:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;EOF&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.cursor/.cursorignore</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">**/.env</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">**/credentials.json</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">**/secrets.json</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">**/*.key</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">**/*.pem</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">**/id_rsa</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">secrets/</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">node_modules/</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EOF</span></span></code></pre></div><h2 id="source-code-analysis" tabindex="-1">Source Code Analysis <a class="header-anchor" href="#source-code-analysis" aria-label="Permalink to &quot;Source Code Analysis&quot;">​</a></h2><p>For white-box pentests where we receive source code, we have an AI enhanced SAST tool: <a href="https://pentestai.internal.syslifters.com/" target="_blank" rel="noreferrer">PentestAI</a>.</p><h3 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h3><p>This tool analyzes source code in stages:</p><ol><li>Discovery: This phase divides the source code into multiple sections. You can choose a model for that</li><li>Planning: In this phase, agents analyze each section from phase 1 against a checklst of vulnerability types. You can choose a model for all the agents.</li><li>Analysis: This is the actual analysis where agents search for vulnerabilities based on reported vuln types from phase 2. You can choose multiple models for all agents.</li><li>Verification: An agent verifies each discovered vulnerability from phase 3. Choose one model for this step.</li><li>Consolidation: Because there are likely duplicate findings, we deduplicate them. Choose a model for this phase as well.</li></ol><h3 id="starting-an-audit" tabindex="-1">Starting an audit <a class="header-anchor" href="#starting-an-audit" aria-label="Permalink to &quot;Starting an audit&quot;">​</a></h3><ol><li>To create an audit, set a project name and upload the source code (either ZIP or folder)</li><li>Start the sandbox and choose a model for the discovery phase</li></ol><p><img src="`+l+'" alt="Start sandbox and choose the model"></p><ol start="3"><li>Next, choose the model used for planning. <strong>When using selfhosted LLMS</strong> make sure to hit the checkbox to force agents to work through the whole checklist.</li></ol><p><img src="'+n+'" alt="Force checklist and select LLM for phase 2"></p><ol start="4"><li>Choose multiple models for analysis</li><li>Choose one model for verification and afterwards consolidation</li></ol>',28)])])}const y=i(o,[["render",r]]);export{g as __pageData,y as default};
